// Bundles deploy/pglite/{schema,data}.sql into a TS module so the in-memory demo
// database (src/server/db/pglite.ts) ships inside the app bundle — no file tracing needed.
// Re-run after changing either SQL file:  node scripts/build-demo-sql.mjs
import { readFileSync, writeFileSync } from 'node:fs';

const read = (f) => readFileSync(new URL(`../deploy/pglite/${f}`, import.meta.url), 'utf8');
const out =
  '// GENERATED by scripts/build-demo-sql.mjs — do not edit.\n' +
  `export const DEMO_SCHEMA_SQL = ${JSON.stringify(read('schema.sql'))};\n` +
  `export const DEMO_DATA_SQL = ${JSON.stringify(read('data.sql'))};\n`;
writeFileSync(new URL('../src/server/db/demo-sql.generated.ts', import.meta.url), out);
console.log('wrote src/server/db/demo-sql.generated.ts', (out.length / 1024).toFixed(0) + ' KB');
